args <- commandArgs(trailingOnly = TRUE); value <- function(flag, default = NULL) { i <- match(flag, args); if (is.na(i)) default else args[i + 1L] }
config <- value("--config", "config/facility_exchange_demo.yml"); source("R/read_facility_exchange_config.R"); cfg <- read_facility_exchange_config(config); source("R/write_controlled_multirun_ledger.R")
directory <- file.path(cfg$outputs$root_directory, "controlled_multirun"); ledger <- readRDS(file.path(directory, "controlled_multirun_ledger.rds"))
rows <- lapply(seq_len(nrow(ledger)), function(i) { run <- ledger$run_id[i]; root <- dirname(ledger$metadata_path[i]); parsed <- file.path(root, "parsed"); receptor <- file.path(root, "receptors", "source_receptor_exchange.csv"); dispersion <- file.path(parsed, "dispersion_filtered.csv"); raw <- file.path(parsed, "dispersion_standardized.csv"); raster <- file.path(parsed, "raster_layer_metadata.csv"); d <- if (file.exists(dispersion)) utils::read.csv(dispersion) else data.frame(); raw_data <- if (file.exists(raw)) utils::read.csv(raw) else data.frame(); r <- if (file.exists(receptor)) utils::read.csv(receptor) else data.frame(); z <- if (file.exists(raster)) utils::read.csv(raster) else data.frame(); data.frame(run_id = run, execution_status = ledger$execution_status[i], raw_record_count = nrow(raw_data), within_20km_count = nrow(d), raster_layer_count = nrow(z), receptor_row_count = nrow(r), intercept_count = if (nrow(r) && "intercept" %in% names(r)) sum(r$intercept) else 0L, unique_sources = if (nrow(r) && "source_id" %in% names(r)) length(unique(r$source_id)) else 0L, unique_receptors = if (nrow(r) && "receptor_id" %in% names(r)) length(unique(r$receptor_id)) else 0L, directed_dyads = if (nrow(r) && all(c("source_id", "receptor_id") %in% names(r))) length(unique(paste(r$source_id, r$receptor_id, sep = "__"))) else 0L, runtime_seconds = ledger$elapsed_seconds[i], stringsAsFactors = FALSE) }); summary <- do.call(rbind, rows)
utils::write.csv(summary, file.path(directory, "controlled_multirun_summary.csv"), row.names = FALSE); saveRDS(summary, file.path(directory, "controlled_multirun_summary.rds")); print(summary, row.names = FALSE); cat("completed runs:", sum(summary$execution_status == "completed"), " failed runs:", sum(summary$execution_status == "failed"), " total runtime seconds:", sum(summary$runtime_seconds, na.rm = TRUE), "\n", sep = "")
